qss:
/* Phosphor is the example of what the `qss` block is for: everything here is
   something the thirteen colours cannot say. */

/* A terminal has no rounded corners. */
#Card, #ChannelStrip, #ContentPanel { border-radius: 2px; }
#Segmented, #Segmented QPushButton { border-radius: 1px; }
QPushButton { border-radius: 2px; }
QSlider::handle:horizontal, QSlider::handle:vertical { border-radius: 1px; }

/* ...and it is monospaced, with the letter-spacing of a character cell. */
* { font-family: "JetBrains Mono", "DejaVu Sans Mono", monospace; }
#PageTitle { letter-spacing: 2px; text-transform: uppercase; }
#ChannelName { letter-spacing: 1px; }

/* A faint scanline-ish separation between the strips. */
#ChannelStrip { border: 1px solid #1f3a24; }
